// Neon Light Runner – minimal implementation
// Targets <canvas id="game"></canvas>

(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const W = canvas.width = canvas.offsetWidth || 800;
  const H = canvas.height = canvas.offsetHeight || 200;

  // Game state
  let score = 0;
  let energy = 1; // 0‑1 range
  let lastTime = 0;
  const ship = {x: 80, y: H/2, w: 30, h: 20, vy: 0, gravity: 0.4, jump: -8};
  const obstacles = [];
  const orbs = [];

  // Input – tap / click to ascend
  const onPress = () => { ship.vy = ship.jump; };

input.oldString:
ctx.fillStyle = '#111';
ctx.fillRect(0,0,W,H);
// neon ship
ctx.fillStyle = '#0ff';
ctx.fillRect(ship.x, ship.y, ship.w, ship.h);
// obstacles
ctx.fillStyle = '#f44';
obstacles.forEach(o => ctx.fillRect(o.x, o.y, o.w, o.h));
// orbs
ctx.fillStyle = '#ff0';
orbs.forEach(o => { ctx.beginPath(); ctx.arc(o.x, o.y, o.r, 0, Math.PI*2); ctx.fill(); });

input.newString:
// Background gradient (dark to deep blue)
const bgGrad = ctx.createLinearGradient(0, 0, 0, H);
bgGrad.addColorStop(0, '#001');
bgGrad.addColorStop(1, '#000');
ctx.fillStyle = bgGrad;
ctx.fillRect(0, 0, W, H);

// Neon ship – triangle with glow
ctx.save();
ctx.translate(ship.x + ship.w / 2, ship.y + ship.h / 2);
ctx.fillStyle = '#0ff';
ctx.shadowColor = '#0ff';
ctx.shadowBlur = 15;
ctx.beginPath();
ctx.moveTo(-ship.w / 2, ship.h / 2);
ctx.lineTo(ship.w / 2, ship.h / 2);
ctx.lineTo(0, -ship.h / 2);
ctx.closePath();
ctx.fill();
ctx.restore();

// Obstacles – spikes with neon red glow
ctx.shadowColor = '#f44';
ctx.shadowBlur = 10;
ctx.fillStyle = '#f44';
obstacles.forEach(o => {
  ctx.save();
  ctx.translate(o.x + o.w / 2, o.y + o.h / 2);
  ctx.beginPath();
  ctx.moveTo(-o.w / 2, o.h / 2);
  ctx.lineTo(o.w / 2, o.h / 2);
  ctx.lineTo(0, -o.h / 2);
  ctx.closePath();
  ctx.fill();
  ctx.restore();
});
ctx.shadowBlur = 0; // reset blur for orbs

// Orbs – glowing yellow circles with radial gradient
orbs.forEach(o => {
  const grad = ctx.createRadialGradient(o.x, o.y, 0, o.x, o.y, o.r);
  grad.addColorStop(0, '#ff0');
  grad.addColorStop(0.6, '#ff0');
  grad.addColorStop(1, 'rgba(255,255,0,0)');
  ctx.fillStyle = grad;
  ctx.beginPath();
  ctx.arc(o.x, o.y, o.r, 0, Math.PI * 2);
  ctx.fill();
});

